-- Speglar det som lades på databasen 2026-09-21 via apply_migration i sju delar:
--   sy_order_code_from_catalogue_part_01  (backup, schema, familj)
--   sy_order_code_from_catalogue_part_02  (parametrar)
--   sy_order_code_from_catalogue_part_03  (värdelista, rensning av regler)
--   sy_order_code_from_catalogue_part_04  (regler 1–20)
--   sy_order_code_from_catalogue_part_05  (regler 21–40)
--   sy_order_code_from_catalogue_part_06  (regler 41–68, dokumentkarta)
--   sy_order_code_from_catalogue_part_07  (produktraden döpt om, gamla dokumentkopplingar bort)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts sy,
-- scripts/fingerprint-values.py):
--   regler  68   md5 1393abfba9dc780642adeed15ee09ad6   villkor 7527aa4b838ebb2d56968ed7f0e95a92
--   värden 129   md5 b7aa27f438ebbd27bd11e394845b9bd2
--   schema       md5 615e5e14e9294a11d90ec8941c7442c0
-- Verifierat live: /sv/configurator/sy bygger SS5Y3-10S6Q2-05U-C6 (nyckelns exempel sida 502),
-- SS5Y3-10S6Q72-05B-C6 (sida 503), SS5Y3-12S6Q72-05B (sida 513) och SS5Y3-12S6Q72-05B-ND0
-- (SMC:s konfigurator); stoppar A/B-port på topportad ramp och DIN-skena D3 för fem platser.
--
-- SY (ventilrampen): beställnyckeln enligt SMC 5-Port Solenoid Valve SY3000/5000/7000 Series (sida 502–503 och 512–513).
-- GENERERAD ur src/lib/catalog/sy-manifold.ts -- redigera inte för hand.
--
-- Rättar familjen sy, som hade mallen 'SY-{stations}-{fieldbus}-{voltage}' med
-- påhittade värden. SMC:s rampkod är
-- SS5Y{serie}-{typ}S6{SI-enhet}{polaritet}{I/O}-{platser}{P/E}{port}{montering}{skena},
-- t.ex. SS5Y3-10S6Q2-05U-C6 (nyckelns exempel sida 502), SS5Y3-10S6Q72-05B-C6
-- (sida 503) och SS5Y3-12S6Q72-05B (topportad, sida 513). Portkoden bär sitt
-- bindestreck så att den topportade rampen utan tumportar inte får ett ensamt
-- "-" före monteringen (SMC:s konfigurator: SS5Y3-12S6Q2-05BD3 och
-- SS5Y3-12S6Q22-05B-ND0).
--
-- Produktraden SMC-SY döps om till SMC-SS5Y5-10S6F4-08B-C8 (SY5000, PROFINET EX600-SPN1,
-- åtta platser) och får katalogens data. Dokumentkartan rensas från JSY-
-- manualerna (annan serie) och den äldre SY-katalogen.

begin;


create schema if not exists backup;
create table if not exists backup.sy_before_20260921 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'sy'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'sy'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'sy';

