update configurator_families set
  title = 'Ventilramp SY3000/5000/7000 plug-in typ 10/11/12 med fältbussenhet EX600, 2–24 platser',
  description = 'SMC SY3000/5000/7000 plug-in connector connecting base manifold (type 10 side ported, 11 bottom ported, 12 top ported) with the EX600 serial transmission SI unit: DeviceNet, PROFIBUS DP, CC-Link, EtherNet/IP, EtherCAT, PROFINET (with or without IO-Link unit) or wireless, PNP/NPN with M12 or 7/8 inch power end plate, up to 9 I/O units, 2–24 valve stations (max. 32 solenoids), P/E ports on the U/D/both sides with internal or external pilot or built-in silencer, A/B One-touch fittings ø2–ø12 or inch, straight or elbow, direct or DIN rail mounting, IP67. Valves ordered per station (family sy-plugin).',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'SS5Y{series}-{type}S6{si_unit}{polarity}{io_stations}-{stations}{pe_entry}{port}{mounting}{din_rail}',
  rules_schema_id = 'SCHEMA-SY-V1'
where slug = 'sy';


