       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"info","if_json":{"==":[{"var":"type"},"10"]},"message_sv":"Ventilerna beställs per station med egen kod (familjen sy-plugin): SY□100-5U1 osv., ventilen närmast D-sidan är station 1 (sida 503).","message_en":"The valves are ordered per station with their own number (family sy-plugin): SY□100-5U1 etc., the valve closest to the D side is station 1 (page 503).","goto_step":"sy-type"},{"severity":"info","if_json":{"==":[{"var":"type"},"11"]},"message_sv":"Ventilerna beställs per station med egen kod (familjen sy-plugin): SY□100-5U1 osv., ventilen närmast D-sidan är station 1 (sida 503).","message_en":"The valves are ordered per station with their own number (family sy-plugin): SY□100-5U1 etc., the valve closest to the D side is station 1 (page 503).","goto_step":"sy-type"},{"severity":"info","if_json":{"==":[{"var":"type"},"12"]},"message_sv":"Ventilerna beställs per station med egen kod (familjen sy-plugin): SY□130-5U1 osv., ventilen närmast D-sidan är station 1; topportade ventiler bär A/B-porten (t.ex. SY3130-5U1-C6) (sida 513).","message_en":"The valves are ordered per station with their own number (family sy-plugin): SY□130-5U1 etc., the valve closest to the D side is station 1; top-ported valves carry the A/B port (e.g. SY3130-5U1-C6) (page 513).","goto_step":"sy-type"},{"severity":"info","if_json":{"==":[{"var":"mounting"},"AA"]},"message_sv":"AA: direktmontering, med namnskylt och stationsnummer (sida 503).","message_en":"AA: direct mounting, with name plate and station numbers (page 503).","goto_step":"sy-mounting"},{"severity":"info","if_json":{"==":[{"var":"mounting"},"BA"]},"message_sv":"BA: direktmontering, med namnskylt (sida 503).","message_en":"BA: direct mounting, with name plate (page 503).","goto_step":"sy-mounting"},{"severity":"info","if_json":{"==":[{"var":"mounting"},"D"]},"message_sv":"D: DIN-skena (fastsättning sida 708) (sida 503).","message_en":"D: DIN rail mounting (fixation on page 708) (page 503).","goto_step":"sy-mounting"},{"severity":"info","if_json":{"==":[{"var":"mounting"},"A"]},"message_sv":"A: DIN-skena (fastsättning sida 708), med namnskylt och stationsnummer (sida 503).","message_en":"A: DIN rail mounting (fixation on page 708), with name plate and station numbers (page 503).","goto_step":"sy-mounting"},{"severity":"info","if_json":{"==":[{"var":"mounting"},"B"]},"message_sv":"B: DIN-skena (fastsättning sida 708), med namnskylt (sida 503).","message_en":"B: DIN rail mounting (fixation on page 708), with name plate (page 503).","goto_step":"sy-mounting"}]'::jsonb) r;

insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-sy-new.pdf', 'sy', 'SMC — SMC 5-Port Solenoid Valve SY3000/5000/7000 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  sku = 'SMC-SS5Y5-10S6F4-08B-C8',
  family = 'SY',
  name = 'SS5Y5-10S6F4-08B-C8 SY5000 valve terminal, 8 stations, PROFINET (EX600)',
  description = 'SMC SY5000 plug-in connector connecting base manifold SS5Y5-10S6F4-08B-C8: type 10 side ported, EX600 PROFINET SI unit EX600-SPN1 (PNP, negative common) with end plate EX600-ED2 (M12 B-coded power), 8 valve stations with double wiring, P/E ports ø10 on both sides, A/B ports ø8 One-touch fittings, internal pilot, direct mounting, IP67. Valves (SY5100-5U1 etc.) are ordered per station; other EX600 units (DeviceNet, PROFIBUS DP, CC-Link, EtherNet/IP, EtherCAT, wireless) and 2–24 stations via the configurator. Catalogue pages 502–503.',
  fieldbus = 'PROFINET',
  voltage = '24 VDC'
where sku = 'SMC-SY';

update product_specs s set value = x.value, unit = x.unit
from products p, (values
  ('fieldbus', 'PROFINET (EX600-SPN1); DeviceNet, PROFIBUS DP, CC-Link, EtherNet/IP, EtherCAT, wireless with other SI unit', null),
  ('flow_rate_l_min', 'C 3.3 dm³/(s·bar) 1→4/2 (SY5000 type 10, 2-position rubber seal valve)', null),
  ('max_pressure', '7', 'bar'),
  ('stations', '8 (manifold available with 2–24)', 'stations'),
  ('solenoid_voltage', '24 VDC', null),
  ('temp_range', '-10 to +50', '°C')
) as x(key, value, unit)
where s.product_id = p.id and p.sku = 'SMC-SS5Y5-10S6F4-08B-C8' and s.key = x.key;

insert into product_specs (product_id, key, value, unit)
select p.id, x.key, x.value, x.unit
from products p
cross join lateral (values
  ('series', 'SY5000', null),
  ('manifold_type', 'Type 10 side ported, plug-in connector connecting base', null),
  ('si_unit', 'EX600-SPN1 (PROFINET, PNP)', null),
  ('port_size', 'A/B ø8, P/E ø10 One-touch fittings', null),
  ('ip_rating', 'IP67', null),
  ('weight_g', '996', 'g'),
  ('order_code_example', 'SS5Y5-10S6F4-08B-C8', null),
  ('catalogue', 'SMC SY3000/5000/7000, How to Order Manifolds sida 502–503 (EX600 typ 10/11), 512–513 (typ 12), data sida 426–427', null)
) as x(key, value, unit)
where p.sku = 'SMC-SS5Y5-10S6F4-08B-C8'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);

update products set ip_rating = 'IP67' where sku = 'SMC-SS5Y5-10S6F4-08B-C8' and ip_rating is null;

-- Dokumentkartan pekade på JSY-manualer (annan serie) och den äldre
-- SY-katalogen; bara det nya kapitlet hör till rampen.
delete from knowledge_doc_families where family_slug = 'sy' and source_file <> 'smc-kat-sy-new.pdf';


commit;

